insert into public.skill_prerequisites(skill_id, prerequisite_skill_id, minimum_status)
select s.id,p.id,'MASTERED' from links l join public.skills s on s.slug=l.skill_slug join public.skills p on p.slug=l.prereq_slug
on conflict (skill_id, prerequisite_skill_id) do update set minimum_status='MASTERED';


-- Original migration: 20260825152319_backend_platform_foundation_v1.sql
begin;

-- Core profile fields that should no longer live only in profile_data JSON.
alter table public.profiles
  add column if not exists gender text,
  add column if not exists current_class_since timestamptz not null default now();

-- Boss state becomes authoritative in Postgres.
alter table public.boss_quests
  add column if not exists max_hp integer not null default 100,
  add column if not exists hp integer not null default 100,
  add column if not exists system_assigned boolean not null default true;

alter table public.boss_quests
  drop constraint if exists boss_quests_hp_check,
  add constraint boss_quests_hp_check check (max_hp > 0 and hp >= 0 and hp <= max_hp);

create table if not exists public.boss_damage_events (
  id bigint generated by default as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  boss_quest_id bigint not null references public.boss_quests(id) on delete cascade,
  source_type text not null,
  source_id text,
  source_name text,
  damage integer not null check (damage > 0),
  hp_before integer not null,
  hp_after integer not null,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create index if not exists boss_damage_events_user_created_idx
  on public.boss_damage_events(user_id, created_at desc);
create index if not exists boss_damage_events_boss_idx
  on public.boss_damage_events(boss_quest_id, created_at desc);

-- GPS/movement becomes first-class backend data.
create table if not exists public.gps_sessions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  quest_id uuid references public.user_quests(id) on delete set null,
  workout_session_id bigint references public.user_workout_sessions(id) on delete set null,
  activity_type text not null default 'MOVEMENT',
  status text not null default 'STARTED',
  target_distance_km numeric,
  target_duration_seconds integer,
  distance_km numeric not null default 0,
  duration_seconds integer not null default 0,
  pace_seconds_per_km numeric,
  route jsonb not null default '[]'::jsonb,
  gps_verified boolean not null default false,
  started_at timestamptz not null default now(),
  ended_at timestamptz,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists gps_sessions_user_started_idx
  on public.gps_sessions(user_id, started_at desc);
create index if not exists gps_sessions_verified_idx
  on public.gps_sessions(user_id, gps_verified, started_at desc);

-- Routines/sleep schedule moves out of profile_data.
create table if not exists public.player_routines (
  user_id uuid primary key references auth.users(id) on delete cascade,
  shift_mode text not null default 'STANDARD',
  sleep_time time,
  wake_time time,
  sleep_minutes integer not null default 480,
  verification_minutes integer not null default 15,
  timezone text not null default 'UTC',
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint player_routines_sleep_minutes_check check (sleep_minutes between 60 and 960)
);

-- Class switching is tracked instead of overwriting history.
create table if not exists public.class_history (
  id bigint generated by default as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  from_class text,
  to_class text not null,
  reason text not null default 'INITIAL',
  trial_status text,
  changed_at timestamptz not null default now(),
  metadata jsonb not null default '{}'::jsonb
);

create index if not exists class_history_user_changed_idx
  on public.class_history(user_id, changed_at desc);

-- Weekly report snapshots are backend-generated and UI-agnostic.
create table if not exists public.weekly_system_reports (
  id bigint generated by default as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  week_start date not null,
  week_end date not null,
  xp_gained integer not null default 0,
  quests_completed integer not null default 0,
  quests_failed integer not null default 0,
  workouts_completed integer not null default 0,
  gps_distance_km numeric not null default 0,
  skills_mastered integer not null default 0,
  boss_damage integer not null default 0,
  bosses_defeated integer not null default 0,
  strongest_attribute text,
  weakest_attribute text,
  recommendation text,
  summary jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  unique(user_id, week_start)
);

-- System Intelligence persistence, ready for later AI backend.
create table if not exists public.system_intelligence_threads (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  title text,
  status text not null default 'ACTIVE',
  context jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.system_intelligence_messages (
  id bigint generated by default as identity primary key,
  thread_id uuid not null references public.system_intelligence_threads(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  role text not null check (role in ('USER','SYSTEM','ASSISTANT')),
  content text not null,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create index if not exists system_intelligence_messages_thread_idx
  on public.system_intelligence_messages(thread_id, created_at);

