  elsif v_lib.quest_type = 'MUST' and v_uq.status in ('ASSIGNED','DECLINED') then
    update public.user_quests
    set
      status = 'ACCEPTED',
      accepted_at = now(),
      expires_at = now() + interval '24 hours',
