-- Original migration: 20260912104032_live_quest_time_and_streaks.sql
-- THE SYSTEM 2.7.0
-- Server-owned Must windows and daily streak reconciliation.

-- Repair historic Must rows before enforcing the invariant. The original
-- accept adapter could reset expires_at after a DECLINED directive while
-- retaining the old accepted_at, which produced windows such as 29 hours.
update public.user_quests
set
  expires_at = accepted_at + interval '24 hours',
  updated_at = now()
where upper(coalesce(quest_type, '')) = 'MUST'
  and accepted_at is not null
  and expires_at is not null
  and expires_at <> accepted_at + interval '24 hours';

alter table public.user_quests
  drop constraint if exists user_quests_must_exactly_24h_check;

alter table public.user_quests
  add constraint user_quests_must_exactly_24h_check
  check (
    upper(coalesce(quest_type, '')) <> 'MUST'
    or accepted_at is null
    or expires_at is null
    or expires_at = accepted_at + interval '24 hours'
  );

create index if not exists user_quests_daily_streak_lookup_idx
  on public.user_quests (user_id, assigned_for desc)
  where upper(coalesce(quest_type, '')) = 'DAILY'
    and status = 'COMPLETED';

create or replace function public.system_recalculate_daily_streak()
returns jsonb
language plpgsql
security definer
set search_path to 'public', 'auth'
as $function$
declare
  v_user uuid := auth.uid();
  v_timezone text;
  v_today date;
  v_anchor date;
  v_cursor date;
  v_streak integer := 0;
begin
  if v_user is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  -- The routine timezone is already saved server-side. Falling back to UTC
  -- keeps the calculation deterministic if a player has not configured one.
  select nullif(btrim(timezone), '')
  into v_timezone
  from public.player_routines
  where user_id = v_user
  limit 1;

  v_timezone := coalesce(v_timezone, 'UTC');

  begin
    v_today := (now() at time zone v_timezone)::date;
  exception
    when invalid_parameter_value then
      v_timezone := 'UTC';
      v_today := (now() at time zone v_timezone)::date;
  end;

  -- A daily streak is one verified DAILY quest per calendar day. Completing
  -- several quests on the same day cannot inflate it. Until today's daily is
  -- complete, yesterday remains the last eligible streak day.
  if exists (
    select 1
    from public.user_quests
    where user_id = v_user
      and upper(coalesce(quest_type, '')) = 'DAILY'
      and status = 'COMPLETED'
      and assigned_for = v_today
  ) then
    v_anchor := v_today;
  else
    v_anchor := v_today - 1;
  end if;

  v_cursor := v_anchor;

  while exists (
    select 1
    from public.user_quests
    where user_id = v_user
      and upper(coalesce(quest_type, '')) = 'DAILY'
      and status = 'COMPLETED'
      and assigned_for = v_cursor
  ) loop
    v_streak := v_streak + 1;
    v_cursor := v_cursor - 1;
  end loop;

  update public.profiles
  set
    streak = v_streak,
    updated_at = now()
  where id = v_user;

  return jsonb_build_object(
    'streak', v_streak,
    'timezone', v_timezone,
    'anchor_day', v_anchor,
    'server_now', now()
  );
end;
$function$;

revoke all on function public.system_recalculate_daily_streak() from public, anon;
grant execute on function public.system_recalculate_daily_streak() to authenticated;

create or replace function public.system_complete_quest(
  p_user_quest_id uuid,
  p_metadata jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path to 'public', 'auth'
as $function$
declare
  v_user uuid := auth.uid();
  v_quest public.user_quests;
  v_profile public.profiles;
  v_streak jsonb;
begin
  if v_user is null then raise exception 'AUTH_REQUIRED'; end if;

  select * into v_quest
  from public.user_quests
  where id = p_user_quest_id and user_id = v_user
  for update;

  if not found then raise exception 'QUEST_NOT_FOUND'; end if;
  if v_quest.status = 'COMPLETED' then raise exception 'QUEST_ALREADY_COMPLETED'; end if;
  if v_quest.status = 'FAILED' then raise exception 'QUEST_ALREADY_FAILED'; end if;
  if v_quest.expires_at is not null and v_quest.expires_at < now() then raise exception 'QUEST_EXPIRED'; end if;

  update public.user_quests
  set
    status = 'COMPLETED',
    completed_at = now(),
    updated_at = now(),
    metadata = coalesce(metadata, '{}'::jsonb) || coalesce(p_metadata, '{}'::jsonb)
  where id = v_quest.id
  returning * into v_quest;

  select * into v_profile from public.system_award_xp(
    v_quest.xp_reward,
    'QUEST',
    v_quest.title_snapshot,
    jsonb_build_object('user_quest_id', v_quest.id, 'quest_type', v_quest.quest_type)
  );

  if v_quest.attribute_reward is not null and v_quest.attribute_delta <> 0 then
    perform public.system_add_attribute(
      v_quest.attribute_reward,
      v_quest.attribute_delta,
      'QUEST',
      v_quest.title_snapshot,
      jsonb_build_object('user_quest_id', v_quest.id)
    );
  end if;

  insert into public.journey_events(
    user_id, event_type, title, detail, source, source_id, xp_delta, metadata
  ) values (
    v_user,
    'QUEST_COMPLETE',
    v_quest.title_snapshot,
    v_quest.objective_snapshot,
    'QUEST',
    v_quest.id::text,
    v_quest.xp_reward,
    coalesce(p_metadata, '{}'::jsonb)
  );

  v_streak := public.system_recalculate_daily_streak();
  select * into v_profile from public.profiles where id = v_user;

  return jsonb_build_object(
    'quest', to_jsonb(v_quest),
    'profile', to_jsonb(v_profile),
    'streak', v_streak
  );
end;
$function$;

create or replace function public.system_accept_quest_by_title_v2(
  p_title text,
  p_duration_seconds integer default 86400,
  p_metadata jsonb default '{}'::jsonb,
  p_assigned_for date default null::date
)
returns jsonb
language plpgsql
security definer
set search_path to 'public', 'auth'
as $function$
declare
  v_user uuid := auth.uid();
  v_profile public.profiles;
  v_lib public.quest_library;
  v_uq public.user_quests;
  v_for_date date := coalesce(p_assigned_for, current_date);
  v_duration integer := 86400;
  v_legacy_key text := nullif(trim(coalesce(p_metadata->>'legacy_key', '')), '');
  v_lock_identity text;
begin
  if v_user is null then raise exception 'AUTH_REQUIRED'; end if;

  select * into v_profile from public.profiles where id = v_user;
  if not found then raise exception 'PROFILE_NOT_READY'; end if;

  select * into v_lib
  from public.quest_library q
  where q.active = true
    and upper(q.title) = upper(trim(p_title))
    and q.quest_type = 'MUST'
    and q.min_level <= coalesce(v_profile.level, 1)
    and (
      q.class_affinity is null
      or cardinality(q.class_affinity) = 0
      or upper(v_profile.class) = any(q.class_affinity)
    )
  limit 1;

  if not found then raise exception 'MUST_QUEST_NOT_AVAILABLE'; end if;

  v_lock_identity := coalesce(v_legacy_key, v_lib.id::text);
  perform pg_advisory_xact_lock(
    hashtextextended(v_user::text || ':' || v_for_date::text || ':' || v_lock_identity, 0)
  );

  if v_legacy_key is not null then
    update public.user_quests uq
    set
      status = 'DECLINED',
      updated_at = now(),
      metadata = coalesce(uq.metadata, '{}'::jsonb)
        || jsonb_build_object(
          'closed_reason', 'SUPERSEDED_DIRECTIVE',
          'closed_at', now(),
          'superseded_by', v_lib.title
        )
    where uq.user_id = v_user
      and uq.assigned_for = v_for_date
      and uq.status in ('ASSIGNED', 'ACCEPTED')
      and nullif(uq.metadata->>'legacy_key', '') = v_legacy_key
      and uq.quest_id is distinct from v_lib.id;
  end if;

  select * into v_uq
  from public.user_quests
  where user_id = v_user
    and quest_id = v_lib.id
    and assigned_for = v_for_date
  limit 1
  for update;

  if found and v_uq.status = 'COMPLETED' then
    return jsonb_build_object(
      'duplicate', true,
      'quest', to_jsonb(v_uq),
      'server_now', now(),
      'assigned_for', v_for_date
    );
  end if;

  if found and v_uq.status = 'FAILED' then
    raise exception 'QUEST_ALREADY_FAILED';
  end if;

  if not found then
    insert into public.user_quests(
      user_id, quest_id, assigned_for, quest_type, title_snapshot,
      objective_snapshot, category, status, source, accepted_at, expires_at,
      xp_reward, xp_penalty, attribute_reward, attribute_delta,
      consequence, metadata
    ) values (
      v_user, v_lib.id, v_for_date, v_lib.quest_type, v_lib.title,
      v_lib.objective, v_lib.category, 'ACCEPTED', 'PLATFORM_V2', now(),
      now() + make_interval(secs => v_duration),
      v_lib.xp_reward, v_lib.failure_xp_penalty, v_lib.attribute_reward,
      v_lib.attribute_delta,
      case when coalesce(v_lib.failure_xp_penalty, 0) > 0
        then '-' || v_lib.failure_xp_penalty || ' XP'
        else null end,
      jsonb_build_object(
        'library_code', v_lib.code,
        'adapter', 'TITLE_V2',
        'accepted_by', 'SYSTEM_API',
        'assigned_for', v_for_date
      ) || coalesce(p_metadata, '{}'::jsonb)
    )
    returning * into v_uq;
  else
    update public.user_quests
    set
      status = 'ACCEPTED',
      accepted_at = case
        when status in ('ASSIGNED', 'DECLINED')
          or accepted_at is null
          or expires_at is null
          then now()
        else accepted_at
      end,
      expires_at = case
        when status in ('ASSIGNED', 'DECLINED')
          or accepted_at is null
          or expires_at is null
          then now() + make_interval(secs => v_duration)
        else expires_at
      end,
      metadata = coalesce(metadata, '{}'::jsonb)
        || coalesce(p_metadata, '{}'::jsonb)
        || jsonb_build_object('assigned_for', v_for_date, 'adapter', 'TITLE_V2'),
      updated_at = now()
    where id = v_uq.id
    returning * into v_uq;
  end if;

  return jsonb_build_object(
    'quest', to_jsonb(v_uq),
    'server_now', now(),
    'assigned_for', v_for_date
  );
end;
$function$;

create or replace function public.system_complete_quest_by_title_v2(
  p_title text,
  p_metadata jsonb default '{}'::jsonb,
  p_assigned_for date default null::date
)
returns jsonb
language plpgsql
security definer
set search_path to 'public', 'auth'
as $function$
declare
  v_user uuid := auth.uid();
  v_profile public.profiles;
  v_lib public.quest_library;
  v_uq public.user_quests;
  v_result jsonb;
  v_orchestration jsonb;
  v_for_date date := coalesce(p_assigned_for, current_date);
  v_legacy_key text := nullif(trim(coalesce(p_metadata->>'legacy_key', '')), '');
  v_lock_identity text;
begin
  if v_user is null then raise exception 'AUTH_REQUIRED'; end if;

  select * into v_profile from public.profiles where id = v_user;
  if not found then raise exception 'PROFILE_NOT_READY'; end if;

  select * into v_lib
  from public.quest_library q
  where q.active = true
    and upper(q.title) = upper(trim(p_title))
    and q.min_level <= coalesce(v_profile.level, 1)
    and (
      q.class_affinity is null
      or cardinality(q.class_affinity) = 0
      or upper(v_profile.class) = any(q.class_affinity)
    )
  order by
    case when upper(v_profile.class) = any(coalesce(q.class_affinity, array[]::text[])) then 0 else 1 end,
    case q.quest_type when 'MUST' then 0 when 'CLASS' then 1 when 'DAILY' then 2 else 3 end
  limit 1;

  if not found then raise exception 'QUEST_NOT_AVAILABLE'; end if;

  v_lock_identity := coalesce(v_legacy_key, v_lib.id::text);
  perform pg_advisory_xact_lock(
    hashtextextended(v_user::text || ':' || v_for_date::text || ':' || v_lock_identity, 0)
  );

  if v_legacy_key is not null then
    update public.user_quests uq
    set
      status = 'DECLINED',
      updated_at = now(),
      metadata = coalesce(uq.metadata, '{}'::jsonb)
        || jsonb_build_object(
          'closed_reason', 'SUPERSEDED_DIRECTIVE',
          'closed_at', now(),
          'superseded_by', v_lib.title
        )
    where uq.user_id = v_user
      and uq.assigned_for = v_for_date
      and uq.status in ('ASSIGNED', 'ACCEPTED')
      and nullif(uq.metadata->>'legacy_key', '') = v_legacy_key
      and uq.quest_id is distinct from v_lib.id;
  end if;

  select * into v_uq
  from public.user_quests
  where user_id = v_user
    and quest_id = v_lib.id
    and assigned_for = v_for_date
  limit 1
  for update;

  if found and v_uq.status = 'COMPLETED' then
    perform public.system_recalculate_daily_streak();
    select * into v_profile from public.profiles where id = v_user;
    return jsonb_build_object(
      'duplicate', true,
      'quest', to_jsonb(v_uq),
      'profile', to_jsonb(v_profile),
      'assigned_for', v_for_date
    );
  end if;

  if found and v_uq.status = 'FAILED' then
    raise exception 'QUEST_ALREADY_FAILED';
  end if;

  if not found then
    insert into public.user_quests(
      user_id, quest_id, assigned_for, quest_type, title_snapshot,
      objective_snapshot, category, status, source, accepted_at, expires_at,
      xp_reward, xp_penalty, attribute_reward, attribute_delta,
      consequence, metadata
    ) values (
      v_user, v_lib.id, v_for_date, v_lib.quest_type, v_lib.title,
      v_lib.objective, v_lib.category,
      case when v_lib.quest_type = 'MUST' then 'ACCEPTED' else 'ASSIGNED' end,
      'PLATFORM_V2',
      case when v_lib.quest_type = 'MUST' then now() else null end,
      now() + interval '24 hours',
      v_lib.xp_reward, v_lib.failure_xp_penalty, v_lib.attribute_reward,
      v_lib.attribute_delta,
      case when coalesce(v_lib.failure_xp_penalty, 0) > 0
        then '-' || v_lib.failure_xp_penalty || ' XP'
        else null end,
      jsonb_build_object(
        'library_code', v_lib.code,
        'adapter', 'TITLE_V2',
        'assigned_for', v_for_date
      ) || coalesce(p_metadata, '{}'::jsonb)
    )
    returning * into v_uq;
  elsif v_lib.quest_type = 'MUST' and v_uq.status in ('ASSIGNED', 'DECLINED') then
    update public.user_quests
    set
      status = 'ACCEPTED',
      accepted_at = now(),
      expires_at = now() + interval '24 hours',
      metadata = coalesce(metadata, '{}'::jsonb)
        || coalesce(p_metadata, '{}'::jsonb)
        || jsonb_build_object('assigned_for', v_for_date, 'adapter', 'TITLE_V2'),
      updated_at = now()
    where id = v_uq.id
    returning * into v_uq;
  end if;

  v_result := public.system_complete_quest(
    v_uq.id,
    coalesce(p_metadata, '{}'::jsonb)
      || jsonb_build_object('completion_adapter', 'TITLE_V2', 'assigned_for', v_for_date)
  );

  update public.profiles
  set
    momentum = coalesce(momentum, 0)
      + case when v_lib.quest_type = 'MUST' then 2 else 1 end,
    updated_at = now()
  where id = v_user;

  begin
    v_orchestration := public.system_orchestrate_progression();
  exception when others then
    v_orchestration := jsonb_build_object('error', sqlerrm);
  end;

  select * into v_profile from public.profiles where id = v_user;

  return v_result || jsonb_build_object(
    'profile', to_jsonb(v_profile),
    'library_code', v_lib.code,
    'quest_type', v_lib.quest_type,
    'assigned_for', v_for_date,
    'orchestration', v_orchestration
  );
end;
$function$;

-- Keep the still-supported legacy title adapter from recreating the old
-- inflated streak or non-24-hour Must behavior.
create or replace function public.system_complete_quest_by_title(
  p_title text,
  p_metadata jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path to 'public', 'auth'
as $function$
declare
  v_user uuid := auth.uid();
  v_profile public.profiles;
  v_lib public.quest_library;
  v_uq public.user_quests;
  v_result jsonb;
  v_today date := current_date;
begin
  if v_user is null then raise exception 'AUTH_REQUIRED'; end if;

  select * into v_profile from public.profiles where id = v_user;
  if not found then raise exception 'PROFILE_NOT_READY'; end if;

  select * into v_lib from public.quest_library q
  where q.active = true
    and upper(q.title) = upper(trim(p_title))
    and q.min_level <= coalesce(v_profile.level, 1)
    and (
      q.class_affinity is null
      or cardinality(q.class_affinity) = 0
      or upper(v_profile.class) = any(q.class_affinity)
    )
  order by
    case when upper(v_profile.class) = any(coalesce(q.class_affinity, array[]::text[])) then 0 else 1 end,
    case q.quest_type when 'MUST' then 0 when 'CLASS' then 1 when 'DAILY' then 2 else 3 end
  limit 1;

  if not found then raise exception 'QUEST_NOT_AVAILABLE'; end if;

  select * into v_uq from public.user_quests
  where user_id = v_user
    and quest_id = v_lib.id
    and assigned_for = v_today
  order by created_at desc
  limit 1
  for update;

  if found and v_uq.status = 'COMPLETED' then
    perform public.system_recalculate_daily_streak();
    select * into v_profile from public.profiles where id = v_user;
    return jsonb_build_object(
      'duplicate', true,
      'quest', to_jsonb(v_uq),
      'profile', to_jsonb(v_profile)
    );
  end if;

  if not found then
    insert into public.user_quests(
      user_id, quest_id, assigned_for, quest_type, title_snapshot,
      objective_snapshot, category, status, source, accepted_at, expires_at,
      xp_reward, xp_penalty, attribute_reward, attribute_delta,
      consequence, metadata
    ) values (
      v_user, v_lib.id, v_today, v_lib.quest_type, v_lib.title,
      v_lib.objective, v_lib.category,
      case when v_lib.quest_type = 'MUST' then 'ACCEPTED' else 'ASSIGNED' end,
      'LEGACY_UI_ADAPTER',
      case when v_lib.quest_type = 'MUST' then now() else null end,
      case when v_lib.quest_type = 'MUST'
        then now() + interval '24 hours'
        else ((v_today + 1)::timestamp at time zone 'UTC') end,
      v_lib.xp_reward, v_lib.failure_xp_penalty, v_lib.attribute_reward,
      v_lib.attribute_delta,
      case when coalesce(v_lib.failure_xp_penalty, 0) > 0
        then '-' || v_lib.failure_xp_penalty || ' XP'
        else null end,
      jsonb_build_object('library_code', v_lib.code, 'adapter', 'TITLE')
    )
    returning * into v_uq;
  elsif v_lib.quest_type = 'MUST' and v_uq.status in ('ASSIGNED', 'DECLINED') then
    update public.user_quests
    set
      status = 'ACCEPTED',
      accepted_at = now(),
      expires_at = now() + interval '24 hours',
      updated_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb)
        || coalesce(p_metadata, '{}'::jsonb)
        || jsonb_build_object('adapter', 'TITLE')
    where id = v_uq.id
    returning * into v_uq;
  end if;

  v_result := public.system_complete_quest(
    v_uq.id,
    coalesce(p_metadata, '{}'::jsonb)
      || jsonb_build_object('completion_adapter', 'TITLE')
  );

  update public.profiles
  set
    momentum = coalesce(momentum, 0)
      + case when v_lib.quest_type = 'MUST' then 2 else 1 end,
    updated_at = now()
  where id = v_user;

  select * into v_profile from public.profiles where id = v_user;
  return v_result || jsonb_build_object(
    'profile', to_jsonb(v_profile),
    'library_code', v_lib.code,
    'quest_type', v_lib.quest_type
  );
end;
$function$;

create or replace function public.system_prepare_player_state()
returns jsonb
language plpgsql
security definer
set search_path to 'public', 'auth'
as $function$
declare
  v_user uuid := auth.uid();
  v_penalties jsonb;
  v_quests jsonb;
  v_boss jsonb;
  v_streak jsonb;
  v_orch jsonb;
begin
  if v_user is null then raise exception 'AUTH_REQUIRED'; end if;
  begin v_penalties := public.system_apply_expired_quest_penalties(); exception when others then v_penalties := jsonb_build_object('error', sqlerrm); end;
  begin v_quests := public.system_generate_daily_quests(current_date); exception when others then v_quests := jsonb_build_object('error', sqlerrm); end;
  begin v_boss := public.system_assign_boss(); exception when others then v_boss := jsonb_build_object('error', sqlerrm); end;
  begin v_streak := public.system_recalculate_daily_streak(); exception when others then v_streak := jsonb_build_object('error', sqlerrm); end;
  begin v_orch := public.system_orchestrate_progression(); exception when others then v_orch := jsonb_build_object('error', sqlerrm); end;
  return jsonb_build_object(
    'penalties', v_penalties,
    'quests', v_quests,
    'boss', v_boss,
    'streak', v_streak,
    'orchestration', v_orch,
    'prepared_at', now()
  );
end;
$function$;



-- Original migration: 20260912141342_boss_key_gate.sql
-- THE SYSTEM 2.8.0 — Boss access is a real inventory unlock.

insert into public.item_catalog (
  slug, name, item_type, rarity, power, required_level, bonus_text, icon, metadata, active
) values (
  'raid-entry-key',
  'RAID ENTRY KEY',
  'KEY',
  'RARE',
  0,
  5,
  'Opens the Boss Gate once the bearer has proved a 3-day Daily streak.',
  '🗝',
  jsonb_build_object('unlock', 'BOSS_GATE', 'minimum_streak', 3),
  true
)
on conflict (slug) do update set
  name = excluded.name,
  item_type = excluded.item_type,
  rarity = excluded.rarity,
  required_level = excluded.required_level,
  bonus_text = excluded.bonus_text,
  icon = excluded.icon,
  metadata = excluded.metadata,
  active = true;

create or replace function public.system_ensure_boss_access_key()
returns jsonb
language plpgsql
security definer
set search_path to 'public', 'auth'
as $function$
declare
  v_user uuid := auth.uid();
  v_profile public.profiles;
  v_key public.item_catalog;
  v_inventory public.user_inventory;
  v_eligible boolean;
begin
  if v_user is null then raise exception 'AUTH_REQUIRED'; end if;

  select * into v_profile from public.profiles where id = v_user;
  if not found then raise exception 'PROFILE_NOT_READY'; end if;

  select * into v_key from public.item_catalog where slug = 'raid-entry-key' and active = true;
  if not found then raise exception 'RAID_KEY_NOT_CONFIGURED'; end if;

  select * into v_inventory
  from public.user_inventory
  where user_id = v_user and catalog_item_id = v_key.id
  order by acquired_at asc
  limit 1;

  if found then
    return jsonb_build_object('has_key', true, 'eligible', true, 'key', to_jsonb(v_inventory));
  end if;

  v_eligible := coalesce(v_profile.level, 1) >= 5 and coalesce(v_profile.streak, 0) >= 3;
  if not v_eligible then
    return jsonb_build_object(
      'has_key', false,
      'eligible', false,
      'required_level', 5,
      'required_streak', 3
    );
  end if;

  insert into public.user_inventory (
    user_id, catalog_item_id, source_type, source_id, metadata
  ) values (
    v_user,
    v_key.id,
    'SYSTEM_UNLOCK',
    'BOSS_GATE',
    jsonb_build_object('earned_at_level', v_profile.level, 'earned_at_streak', v_profile.streak)
  ) returning * into v_inventory;

  insert into public.journey_events(user_id, event_type, title, detail, source, source_id, metadata)
  values (
    v_user,
    'KEY_EARNED',
    v_key.name,
    'BOSS GATE UNLOCKED',
    'INVENTORY',
    v_inventory.id::text,
    jsonb_build_object('required_level', 5, 'required_streak', 3)
  );

  return jsonb_build_object('has_key', true, 'eligible', true, 'awarded', true, 'key', to_jsonb(v_inventory));
end;
$function$;

revoke all on function public.system_ensure_boss_access_key() from public, anon;
grant execute on function public.system_ensure_boss_access_key() to authenticated;

create or replace function public.system_assign_boss()
returns jsonb
language plpgsql
security definer
set search_path to 'public', 'auth'
as $function$
declare
  v_user uuid := auth.uid();
  v_profile public.profiles;
  v_existing public.boss_quests;
  v_template public.boss_library;
  v_boss public.boss_quests;
  v_obj text;
  v_pos integer := 0;
  v_key_status jsonb;
begin
  if v_user is null then raise exception 'AUTH_REQUIRED'; end if;

  v_key_status := public.system_ensure_boss_access_key();
  if not coalesce((v_key_status->>'has_key')::boolean, false) then
    return jsonb_build_object('assigned', false, 'reason', 'RAID_KEY_REQUIRED', 'key_status', v_key_status);
  end if;

  select * into v_existing from public.boss_quests where user_id = v_user and status = 'ACTIVE' order by created_at desc limit 1;
  if found then return jsonb_build_object('assigned', false, 'reason', 'ACTIVE_BOSS_EXISTS', 'boss', to_jsonb(v_existing)); end if;

  select * into v_profile from public.profiles where id = v_user;
  select * into v_template from public.boss_library
   where active = true and min_level <= v_profile.level and (max_level is null or max_level >= v_profile.level)
     and (cardinality(class_affinity) = 0 or v_profile.class = any(class_affinity))
   order by case when v_profile.class = any(class_affinity) then 0 else 1 end, rank desc, random()
   limit 1;
  if not found then raise exception 'NO_BOSS_TEMPLATE_AVAILABLE'; end if;

  insert into public.boss_quests(user_id,title,rank,category,deadline,xp_reward,reward_name,reward_rarity,status,system_assigned,max_hp,hp,metadata)
   values(v_user,v_template.title,v_template.rank,v_template.category,now()+interval '7 days',v_template.xp_reward,v_template.reward_name,v_template.reward_rarity,'ACTIVE',true,v_template.max_hp,v_template.max_hp,jsonb_build_object('boss_library_id',v_template.id,'boss_slug',v_template.slug,'raid_key_required',true)) returning * into v_boss;
  for v_obj in select jsonb_array_elements_text(v_template.objective_templates) loop
    v_pos := v_pos + 1;
    insert into public.boss_quest_objectives(user_id,boss_quest_id,objective,position,is_complete) values(v_user,v_boss.id,v_obj,v_pos,false);
  end loop;
  insert into public.journey_events(user_id,event_type,title,detail,source,source_id,metadata)
   values(v_user,'BOSS_ASSIGNED',v_boss.title,v_boss.rank||'-RANK SYSTEM BOSS','BOSS',v_boss.id::text,jsonb_build_object('system_assigned',true,'raid_key_required',true));
  return jsonb_build_object('assigned',true,'boss',to_jsonb(v_boss),'key_status',v_key_status);
end;
$function$;



-- Original migration: 20260914125416_adaptive_directive_repair_v2_8_4.sql
-- THE SYSTEM 2.8.4 — Adaptive directives must be class-compatible Standards.
-- The previous browser-only selector could choose another class's Must quest,
-- which the authoritative completion RPC correctly rejected.

insert into public.quest_library (
  code,
  title,
  objective,
  system_message,
  category,
  quest_type,
  difficulty,
  class_affinity,
  attribute_reward,
  attribute_delta,
  xp_reward,
  failure_xp_penalty,
  duration_minutes,
  min_level,
  health_value,
  procrastination_tag,
  frequency,
  active,
  metadata
) values
  (
    'adaptive_physical_momentum_walk',
    'MOMENTUM WALK',
    'Move for 20 minutes at a safe, self-selected pace. Stop if pain or dizziness appears.',
    'Physical consistency is rebuilt through a controlled, repeatable session.',
    'PHYSICAL',
    'STANDARD',
    'EASY',
    '{}'::text[],
    'ENDURANCE',
    1,
    35,
    0,
    20,
    1,
    5,
    'START_SMALL',
    'ROTATING',
    true,
    jsonb_build_object('adaptive', true, 'proof_type', 'PERFORMANCE')
  ),
  (
    'adaptive_physical_mobility_baseline',
    'MOBILITY BASELINE',
    'Complete 10 minutes of gentle mobility for the areas that feel stiff today. Keep every movement controlled.',
    'Restore range before asking the body for more output.',
    'PHYSICAL',
    'STANDARD',
    'EASY',
    '{}'::text[],
    'SPEED',
    1,
    30,
    0,
    10,
    1,
    4,
    'LOW_FRICTION',
    'ROTATING',
    true,
    jsonb_build_object('adaptive', true, 'proof_type', 'PERFORMANCE')
  ),
  (
    'adaptive_physical_foundation_set',
    'FOUNDATION SET',
    'Complete one short bodyweight or resistance set that matches your current ability, then record the result.',
    'A modest completed set is stronger than an ambitious plan left undone.',
    'PHYSICAL',
    'STANDARD',
    'EASY',
    '{}'::text[],
    'STRENGTH',
    1,
    35,
    0,
    12,
    1,
    4,
    'START_SMALL',
    'ROTATING',
    true,
    jsonb_build_object('adaptive', true, 'proof_type', 'PERFORMANCE')
  )
on conflict (code) do update set
  title = excluded.title,
  objective = excluded.objective,
  system_message = excluded.system_message,
  category = excluded.category,
  quest_type = excluded.quest_type,
  difficulty = excluded.difficulty,
  class_affinity = excluded.class_affinity,
  attribute_reward = excluded.attribute_reward,
  attribute_delta = excluded.attribute_delta,
  xp_reward = excluded.xp_reward,
  failure_xp_penalty = excluded.failure_xp_penalty,
  duration_minutes = excluded.duration_minutes,
  min_level = excluded.min_level,
  health_value = excluded.health_value,
  procrastination_tag = excluded.procrastination_tag,
  frequency = excluded.frequency,
  active = excluded.active,
  metadata = excluded.metadata,
  updated_at = now();

create or replace function public.system_resolve_adaptive_quest_v2(
  p_category_order text[] default array[]::text[]
)
returns jsonb
language plpgsql
security definer
set search_path to 'public', 'auth'
as $function$
declare
  v_user uuid := auth.uid();
  v_profile public.profiles;
  v_order text[] := array[]::text[];
  v_directive public.quest_library;
begin
  if v_user is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  select * into v_profile
  from public.profiles
  where id = v_user;

  if not found then
    raise exception 'PROFILE_NOT_READY';
  end if;

  select coalesce(
    array_agg(source.category order by source.position),
    array[]::text[]
  )
  into v_order
  from (
    select upper(value) as category, min(ordinality) as position
    from unnest(coalesce(p_category_order, array[]::text[]))
      with ordinality as requested(value, ordinality)
    where upper(value) = any(array[
      'PHYSICAL',
      'WEALTH',
      'LEARNING',
      'FOCUS',
      'RECOVERY'
    ])
    group by upper(value)
  ) source;

  if cardinality(v_order) = 0 then
    v_order := array[
      'PHYSICAL',
      'WEALTH',
      'LEARNING',
      'FOCUS',
      'RECOVERY'
    ];
  end if;

  select * into v_directive
  from public.quest_library q
  where q.active = true
    and q.quest_type = 'STANDARD'
    and upper(q.category) = any(v_order)
    and q.min_level <= coalesce(v_profile.level, 1)
    and (
      cardinality(q.class_affinity) = 0
      or upper(coalesce(v_profile.class, '')) = any(q.class_affinity)
    )
  order by
    array_position(v_order, upper(q.category)),
    md5(v_user::text || ':' || current_date::text || ':' || q.code),
    q.health_value desc,
    q.code asc
  limit 1;

  if not found then
    return jsonb_build_object(
      'directive', null,
      'reason', 'NO_COMPATIBLE_ADAPTIVE_DIRECTIVE'
    );
  end if;

  return jsonb_build_object(
    'directive',
    jsonb_build_object(
      'id', v_directive.id,
      'code', v_directive.code,
      'name', v_directive.title,
      'task', v_directive.objective,
      'category', v_directive.category,
      'xp', v_directive.xp_reward,
      'attribute', v_directive.attribute_reward,
      'attribute_delta', v_directive.attribute_delta,
      'proof_type', coalesce(v_directive.metadata->>'proof_type', ''),
      'metadata', v_directive.metadata
    )
  );
end;
$function$;

revoke all on function public.system_resolve_adaptive_quest_v2(text[]) from public, anon;
grant execute on function public.system_resolve_adaptive_quest_v2(text[]) to authenticated;



-- Original migration: 20260914125430_class_attribute_credits_v2_8_5.sql
-- THE SYSTEM 2.8.5 — Class-aligned attributes and server-authoritative credits.
--
-- This migration deliberately does not rewrite earned player attributes. It only
-- calibrates untouched legacy rows that still exactly match the old all-10
-- placeholder defaults, then makes all future quest-credit allocation atomic.

create table if not exists public.attribute_credit_ledger (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  user_quest_id uuid not null unique references public.user_quests(id) on delete cascade,
  source_title text not null,
  source_category text not null,
  eligible_attributes text[] not null,
  credits_awarded integer not null check (credits_awarded between 1 and 3),
  credits_spent integer not null default 0 check (credits_spent >= 0 and credits_spent <= credits_awarded),
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (cardinality(eligible_attributes) between 1 and 3),
  check (
    eligible_attributes <@ array[
      'STRENGTH', 'SPEED', 'ENDURANCE', 'INTELLIGENCE', 'FOCUS',
      'DISCIPLINE', 'WEALTH', 'CHARISMA', 'CREATIVITY', 'RECOVERY'
    ]::text[]
  )
);

create table if not exists public.attribute_credit_allocations (
  id bigint generated always as identity primary key,
  credit_id uuid not null references public.attribute_credit_ledger(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  attribute_name text not null check (
    attribute_name in (
      'STRENGTH', 'SPEED', 'ENDURANCE', 'INTELLIGENCE', 'FOCUS',
      'DISCIPLINE', 'WEALTH', 'CHARISMA', 'CREATIVITY', 'RECOVERY'
    )
  ),
  amount integer not null check (amount between 1 and 3),
  created_at timestamptz not null default now()
);

create index if not exists attribute_credit_ledger_user_pending_idx
  on public.attribute_credit_ledger (user_id, created_at desc)
  where credits_spent < credits_awarded;

create index if not exists attribute_credit_allocations_user_created_idx
  on public.attribute_credit_allocations (user_id, created_at desc);

alter table public.attribute_credit_ledger enable row level security;
alter table public.attribute_credit_allocations enable row level security;

revoke all on table public.attribute_credit_ledger from public, anon, authenticated;
revoke all on table public.attribute_credit_allocations from public, anon, authenticated;
grant select on table public.attribute_credit_ledger to authenticated;
grant select on table public.attribute_credit_allocations to authenticated;

drop policy if exists "Players can view own attribute credit ledger" on public.attribute_credit_ledger;
create policy "Players can view own attribute credit ledger"
  on public.attribute_credit_ledger
  for select
  to authenticated
  using ((select auth.uid()) = user_id);

drop policy if exists "Players can view own attribute allocations" on public.attribute_credit_allocations;
create policy "Players can view own attribute allocations"
  on public.attribute_credit_allocations
  for select
  to authenticated
  using ((select auth.uid()) = user_id);

-- Class defaults are used only for a newly created attributes row. Existing
-- earned values are never overwritten by profile initialization.
create or replace function public.system_initialize_profile(
  p_name text,
  p_age integer,
  p_gender text,
  p_class text,
  p_fingerprint text default null,
  p_profile_data jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_user uuid := auth.uid();
  v_profile public.profiles;
  v_attributes public.attributes;
  v_class text := upper(trim(coalesce(p_class, 'COMMANDER')));
begin
  if v_user is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  if length(trim(coalesce(p_name, ''))) < 2 then
    raise exception 'INVALID_NAME';
  end if;

  if p_age is null or p_age < 13 or p_age > 120 then
    raise exception 'INVALID_AGE';
  end if;

  if v_class not in ('COMMANDER', 'TANK', 'ASSASSIN', 'MAGE', 'RANGER') then
    raise exception 'INVALID_CLASS';
  end if;

  insert into public.profiles(
    id, name, age, gender, class, level, xp, streak, momentum,
    fingerprint, profile_data, current_class_since
  )
  values (
    v_user,
    trim(p_name),
    p_age,
    nullif(trim(coalesce(p_gender, '')), ''),
    v_class,
    1,
    0,
    0,
    0,
    p_fingerprint,
    coalesce(p_profile_data, '{}'::jsonb)
      - array['xp', 'level', 'streak', 'momentum', 'attributes', 'masteredSkills', 'bossQuests', 'rewards', 'customInventory']::text[],
    now()
  )
  on conflict (id) do update
  set
    name = excluded.name,
    age = excluded.age,
    gender = excluded.gender,
    fingerprint = coalesce(public.profiles.fingerprint, excluded.fingerprint),
    profile_data = coalesce(public.profiles.profile_data, '{}'::jsonb) || excluded.profile_data,
    updated_at = now()
  returning * into v_profile;

  insert into public.attributes(
    user_id, strength, speed, endurance, intelligence, focus,
    discipline, wealth, charisma, creativity, recovery
  )
  values (
    v_user,
    case v_class
      when 'MAGE' then 4 when 'COMMANDER' then 5 when 'TANK' then 15 when 'ASSASSIN' then 7 when 'RANGER' then 8
    end,
    case v_class
      when 'MAGE' then 5 when 'COMMANDER' then 5 when 'TANK' then 5 when 'ASSASSIN' then 15 when 'RANGER' then 13
    end,
    case v_class
      when 'MAGE' then 5 when 'COMMANDER' then 6 when 'TANK' then 14 when 'ASSASSIN' then 8 when 'RANGER' then 15
    end,
    case v_class
      when 'MAGE' then 15 when 'COMMANDER' then 8 when 'TANK' then 6 when 'ASSASSIN' then 7 when 'RANGER' then 7
    end,
    case v_class
      when 'MAGE' then 13 when 'COMMANDER' then 11 when 'TANK' then 8 when 'ASSASSIN' then 14 when 'RANGER' then 10
    end,
    case v_class
      when 'MAGE' then 9 when 'COMMANDER' then 13 when 'TANK' then 12 when 'ASSASSIN' then 12 when 'RANGER' then 9
    end,
    case v_class
      when 'MAGE' then 5 when 'COMMANDER' then 10 when 'TANK' then 4 when 'ASSASSIN' then 5 when 'RANGER' then 4
    end,
    case v_class
      when 'MAGE' then 5 when 'COMMANDER' then 15 when 'TANK' then 5 when 'ASSASSIN' then 5 when 'RANGER' then 5
    end,
    case v_class
      when 'MAGE' then 11 when 'COMMANDER' then 7 when 'TANK' then 5 when 'ASSASSIN' then 10 when 'RANGER' then 6
    end,
    case v_class
      when 'MAGE' then 8 when 'COMMANDER' then 8 when 'TANK' then 10 when 'ASSASSIN' then 7 when 'RANGER' then 12
    end
  )
  on conflict (user_id) do nothing;

  select * into v_attributes
  from public.attributes
  where user_id = v_user;

  return jsonb_build_object(
    'profile', to_jsonb(v_profile),
    'attributes', to_jsonb(v_attributes)
  );
end;
$function$;

revoke all on function public.system_initialize_profile(text, integer, text, text, text, jsonb) from public, anon;
grant execute on function public.system_initialize_profile(text, integer, text, text, text, jsonb) to authenticated;

-- Calibrate only untouched legacy placeholder rows. A player who has earned or
-- otherwise changed any attribute keeps every existing value exactly as-is.
update public.attributes a
set
  strength = case upper(p.class) when 'MAGE' then 4 when 'COMMANDER' then 5 when 'TANK' then 15 when 'ASSASSIN' then 7 when 'RANGER' then 8 else a.strength end,
  speed = case upper(p.class) when 'MAGE' then 5 when 'COMMANDER' then 5 when 'TANK' then 5 when 'ASSASSIN' then 15 when 'RANGER' then 13 else a.speed end,
  endurance = case upper(p.class) when 'MAGE' then 5 when 'COMMANDER' then 6 when 'TANK' then 14 when 'ASSASSIN' then 8 when 'RANGER' then 15 else a.endurance end,
  intelligence = case upper(p.class) when 'MAGE' then 15 when 'COMMANDER' then 8 when 'TANK' then 6 when 'ASSASSIN' then 7 when 'RANGER' then 7 else a.intelligence end,
  focus = case upper(p.class) when 'MAGE' then 13 when 'COMMANDER' then 11 when 'TANK' then 8 when 'ASSASSIN' then 14 when 'RANGER' then 10 else a.focus end,
  discipline = case upper(p.class) when 'MAGE' then 9 when 'COMMANDER' then 13 when 'TANK' then 12 when 'ASSASSIN' then 12 when 'RANGER' then 9 else a.discipline end,
  wealth = case upper(p.class) when 'MAGE' then 5 when 'COMMANDER' then 10 when 'TANK' then 4 when 'ASSASSIN' then 5 when 'RANGER' then 4 else a.wealth end,
  charisma = case upper(p.class) when 'MAGE' then 5 when 'COMMANDER' then 15 when 'TANK' then 5 when 'ASSASSIN' then 5 when 'RANGER' then 5 else a.charisma end,
  creativity = case upper(p.class) when 'MAGE' then 11 when 'COMMANDER' then 7 when 'TANK' then 5 when 'ASSASSIN' then 10 when 'RANGER' then 6 else a.creativity end,
  recovery = case upper(p.class) when 'MAGE' then 8 when 'COMMANDER' then 8 when 'TANK' then 10 when 'ASSASSIN' then 7 when 'RANGER' then 12 else a.recovery end,
  updated_at = now()
from public.profiles p
where p.id = a.user_id
  and a.strength = 10
  and a.speed = 10
  and a.endurance = 10
  and a.intelligence = 10
  and a.focus = 10
  and a.discipline = 10
  and a.wealth = 10
  and a.charisma = 10
  and a.creativity = 10
  and a.recovery = 10
  and not exists (
    select 1
    from public.progression_events e
    where e.user_id = a.user_id
      and e.attribute_name is not null
  );

create or replace function public.system_class_credit_attributes_v1(p_class text)
returns text[]
language plpgsql
immutable
set search_path = ''
as $function$
begin
  return case upper(trim(coalesce(p_class, 'COMMANDER')))
    when 'MAGE' then array['INTELLIGENCE', 'FOCUS', 'CREATIVITY']::text[]
    when 'COMMANDER' then array['CHARISMA', 'DISCIPLINE', 'FOCUS']::text[]
    when 'TANK' then array['STRENGTH', 'ENDURANCE', 'DISCIPLINE']::text[]
    when 'ASSASSIN' then array['SPEED', 'FOCUS', 'DISCIPLINE']::text[]
    when 'RANGER' then array['ENDURANCE', 'SPEED', 'RECOVERY']::text[]
    else array['DISCIPLINE', 'FOCUS', 'RECOVERY']::text[]
  end;
end;
$function$;

create or replace function public.system_quest_credit_attributes_v1(
  p_category text,
  p_attribute_reward text,
  p_class text
)
returns text[]
language plpgsql
immutable
set search_path = ''
as $function$
declare
  v_category text := upper(trim(coalesce(p_category, '')));
  v_reward text := upper(trim(coalesce(p_attribute_reward, '')));
  v_attributes text[];
begin
  v_attributes := case v_category
    when 'PHYSICAL' then array['STRENGTH', 'ENDURANCE', 'RECOVERY']::text[]
    when 'LEARNING' then array['INTELLIGENCE', 'FOCUS', 'CREATIVITY']::text[]
    when 'FOCUS' then array['FOCUS', 'DISCIPLINE', 'INTELLIGENCE']::text[]
    when 'DISCIPLINE' then array['DISCIPLINE', 'FOCUS', 'RECOVERY']::text[]
    when 'RECOVERY' then array['RECOVERY', 'ENDURANCE', 'DISCIPLINE']::text[]
    when 'HEALTH' then array['RECOVERY', 'ENDURANCE', 'DISCIPLINE']::text[]
    when 'NUTRITION' then array['RECOVERY', 'ENDURANCE', 'DISCIPLINE']::text[]
    when 'WEALTH' then array['WEALTH', 'DISCIPLINE', 'INTELLIGENCE']::text[]
    when 'SOCIAL' then array['CHARISMA', 'FOCUS', 'DISCIPLINE']::text[]
    when 'HOME' then array['DISCIPLINE', 'FOCUS', 'RECOVERY']::text[]
    when 'HYGIENE' then array['DISCIPLINE', 'RECOVERY', 'FOCUS']::text[]
    when 'CLASS' then public.system_class_credit_attributes_v1(p_class)
    else public.system_class_credit_attributes_v1(p_class)
  end;

  if v_reward in (
    'STRENGTH', 'SPEED', 'ENDURANCE', 'INTELLIGENCE', 'FOCUS',
    'DISCIPLINE', 'WEALTH', 'CHARISMA', 'CREATIVITY', 'RECOVERY'
  ) and not (v_reward = any(v_attributes)) then
    v_attributes := array_prepend(v_reward, v_attributes[1:2]);
  end if;

  return v_attributes;
end;
$function$;

create or replace function public.system_quest_attribute_credit_amount_v1(
  p_quest_type text,
  p_difficulty text
)
returns integer
language sql
immutable
set search_path = ''
as $function$
  select case
    when upper(coalesce(p_difficulty, '')) = 'ELITE' then 3
    when upper(coalesce(p_quest_type, '')) = 'MUST' then 2
    when upper(coalesce(p_difficulty, '')) = 'HARD' then 2
    else 1
  end;
$function$;

revoke all on function public.system_class_credit_attributes_v1(text) from public, anon, authenticated;
revoke all on function public.system_quest_credit_attributes_v1(text, text, text) from public, anon, authenticated;
revoke all on function public.system_quest_attribute_credit_amount_v1(text, text) from public, anon, authenticated;

-- Quest completion stays authoritative. XP is awarded as before, but the old
-- immediate attribute mutation is exchanged for a server-created credit with
-- a server-computed eligible-attribute list and daily earned-credit cap.
create or replace function public.system_complete_quest(
  p_user_quest_id uuid,
  p_metadata jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_user uuid := auth.uid();
  v_quest public.user_quests;
  v_profile public.profiles;
  v_streak jsonb;
  v_credit public.attribute_credit_ledger;
  v_credit_summary jsonb := jsonb_build_object('status', 'NOT_EARNED');
  v_proof_type text := upper(trim(coalesce(p_metadata->>'proof_type', '')));
  v_has_credit_proof boolean := false;
  v_difficulty text := '';
  v_requested_credits integer := 0;
  v_earned_today integer := 0;
  v_granted_credits integer := 0;
  v_daily_credit_cap constant integer := 4;
  v_eligible_attributes text[];
begin
  if v_user is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  select * into v_quest
  from public.user_quests
  where id = p_user_quest_id
    and user_id = v_user
  for update;

  if not found then raise exception 'QUEST_NOT_FOUND'; end if;
  if v_quest.status = 'COMPLETED' then raise exception 'QUEST_ALREADY_COMPLETED'; end if;
  if v_quest.status = 'FAILED' then raise exception 'QUEST_ALREADY_FAILED'; end if;
  if v_quest.expires_at is not null and v_quest.expires_at < now() then raise exception 'QUEST_EXPIRED'; end if;

  update public.user_quests
  set
    status = 'COMPLETED',
    completed_at = now(),
    updated_at = now(),
    metadata = coalesce(metadata, '{}'::jsonb) || coalesce(p_metadata, '{}'::jsonb)
  where id = v_quest.id
  returning * into v_quest;

  select * into v_profile
  from public.system_award_xp(
    v_quest.xp_reward,
    'QUEST',
    v_quest.title_snapshot,
    jsonb_build_object('user_quest_id', v_quest.id, 'quest_type', v_quest.quest_type)
  );

  v_has_credit_proof :=
    v_proof_type in ('TIME', 'PERFORMANCE', 'LEARNING', 'RESULT', 'PHOTO', 'VIDEO', 'GPS', 'HONOR')
    and nullif(trim(coalesce(p_metadata->>'proof_verified_at', '')), '') is not null;

  if v_has_credit_proof then
    select coalesce(q.difficulty, '')
    into v_difficulty
    from public.quest_library q
    where q.id = v_quest.quest_id;

    v_requested_credits := public.system_quest_attribute_credit_amount_v1(
      v_quest.quest_type,
      v_difficulty
    );

    if v_requested_credits = 1 and v_quest.quest_type = 'MUST' then
      v_requested_credits := 2;
    end if;

    select coalesce(sum(credit.credits_awarded), 0)
    into v_earned_today
    from public.attribute_credit_ledger credit
    join public.user_quests completed_quest
      on completed_quest.id = credit.user_quest_id
    where credit.user_id = v_user
      and completed_quest.assigned_for = v_quest.assigned_for;

    v_granted_credits := greatest(
      0,
      least(v_requested_credits, v_daily_credit_cap - v_earned_today)
    );

    if v_granted_credits > 0 then
      v_eligible_attributes := public.system_quest_credit_attributes_v1(
        v_quest.category,
        v_quest.attribute_reward,
        v_profile.class
      );

      insert into public.attribute_credit_ledger(
        user_id,
        user_quest_id,
        source_title,
        source_category,
        eligible_attributes,
        credits_awarded,
        metadata
      )
      values (
        v_user,
        v_quest.id,
        v_quest.title_snapshot,
        v_quest.category,
        v_eligible_attributes,
        v_granted_credits,
        jsonb_build_object(
          'quest_type', v_quest.quest_type,
          'proof_type', v_proof_type,
          'assigned_for', v_quest.assigned_for,
          'daily_credit_cap', v_daily_credit_cap
        )
      )
      on conflict (user_quest_id) do nothing
      returning * into v_credit;

      if v_credit.id is not null then
        v_credit_summary := to_jsonb(v_credit) || jsonb_build_object(
          'status', 'READY',
          'credits_available', v_credit.credits_awarded - v_credit.credits_spent
        );
      else
        v_credit_summary := jsonb_build_object('status', 'ALREADY_RECORDED');
      end if;
    else
      v_credit_summary := jsonb_build_object(
        'status', 'DAILY_CAP_REACHED',
        'daily_credit_cap', v_daily_credit_cap,
        'earned_today', v_earned_today
      );
    end if;
  else
    v_credit_summary := jsonb_build_object('status', 'PROOF_RECEIPT_REQUIRED');
  end if;

  insert into public.journey_events(
    user_id, event_type, title, detail, source, source_id, xp_delta, metadata
  )
  values (
    v_user,
    'QUEST_COMPLETE',
    v_quest.title_snapshot,
    v_quest.objective_snapshot,
    'QUEST',
    v_quest.id::text,
    v_quest.xp_reward,
    coalesce(p_metadata, '{}'::jsonb) || jsonb_build_object('attribute_credit', v_credit_summary)
  );

  v_streak := public.system_recalculate_daily_streak();
  select * into v_profile from public.profiles where id = v_user;

  return jsonb_build_object(
    'quest', to_jsonb(v_quest),
    'profile', to_jsonb(v_profile),
    'streak', v_streak,
    'attribute_credit', v_credit_summary
  );
end;
$function$;

revoke all on function public.system_complete_quest(uuid, jsonb) from public, anon;
grant execute on function public.system_complete_quest(uuid, jsonb) to authenticated;

create or replace function public.system_allocate_attribute_credit_v1(
  p_credit_id uuid,
  p_attribute text,
  p_amount integer default 1
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_user uuid := auth.uid();
  v_credit public.attribute_credit_ledger;
  v_attributes public.attributes;
  v_profile public.profiles;
  v_attribute text := upper(trim(coalesce(p_attribute, '')));
  v_before integer := 0;
  v_after integer := 0;
begin
  if v_user is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  if p_amount is null or p_amount < 1 or p_amount > 3 then
    raise exception 'INVALID_CREDIT_AMOUNT';
  end if;

  if v_attribute not in (
    'STRENGTH', 'SPEED', 'ENDURANCE', 'INTELLIGENCE', 'FOCUS',
    'DISCIPLINE', 'WEALTH', 'CHARISMA', 'CREATIVITY', 'RECOVERY'
  ) then
    raise exception 'INVALID_ATTRIBUTE';
  end if;

  select * into v_credit
  from public.attribute_credit_ledger
  where id = p_credit_id
    and user_id = v_user
  for update;

  if not found then
    raise exception 'ATTRIBUTE_CREDIT_NOT_FOUND';
  end if;

  if v_attribute <> all(v_credit.eligible_attributes) then
    raise exception 'ATTRIBUTE_NOT_ELIGIBLE_FOR_CREDIT';
  end if;

  if v_credit.credits_spent + p_amount > v_credit.credits_awarded then
    raise exception 'INSUFFICIENT_ATTRIBUTE_CREDITS';
  end if;

  insert into public.attributes(user_id)
  values (v_user)
  on conflict (user_id) do nothing;

  select * into v_attributes
  from public.attributes
  where user_id = v_user
  for update;

  v_before := case v_attribute
    when 'STRENGTH' then v_attributes.strength
    when 'SPEED' then v_attributes.speed
    when 'ENDURANCE' then v_attributes.endurance
    when 'INTELLIGENCE' then v_attributes.intelligence
    when 'FOCUS' then v_attributes.focus
    when 'DISCIPLINE' then v_attributes.discipline
    when 'WEALTH' then v_attributes.wealth
    when 'CHARISMA' then v_attributes.charisma
    when 'CREATIVITY' then v_attributes.creativity
    when 'RECOVERY' then v_attributes.recovery
  end;

  execute format(
    'update public.attributes set %I = %I + $1, updated_at = now() where user_id = $2 returning *',
    lower(v_attribute),
    lower(v_attribute)
  )
  into v_attributes
  using p_amount, v_user;

  v_after := case v_attribute
    when 'STRENGTH' then v_attributes.strength
    when 'SPEED' then v_attributes.speed
    when 'ENDURANCE' then v_attributes.endurance
    when 'INTELLIGENCE' then v_attributes.intelligence
    when 'FOCUS' then v_attributes.focus
    when 'DISCIPLINE' then v_attributes.discipline
    when 'WEALTH' then v_attributes.wealth
    when 'CHARISMA' then v_attributes.charisma
    when 'CREATIVITY' then v_attributes.creativity
    when 'RECOVERY' then v_attributes.recovery
  end;

  update public.attribute_credit_ledger
  set
    credits_spent = credits_spent + p_amount,
    updated_at = now()
  where id = v_credit.id
  returning * into v_credit;

  insert into public.attribute_credit_allocations(
    credit_id, user_id, attribute_name, amount
  )
  values (
    v_credit.id, v_user, v_attribute, p_amount
  );

  select * into v_profile
  from public.profiles
  where id = v_user;

  insert into public.progression_events(
    user_id, event_type, source, title, xp_delta,
    level_before, level_after, attribute_name, attribute_delta, metadata
  )
  values (
    v_user,
    'ATTRIBUTE_CREDIT_ALLOCATED',
    'ATTRIBUTE_CREDIT',
    v_credit.source_title,
    0,
    v_profile.level,
    v_profile.level,
    v_attribute,
    v_after - v_before,
    jsonb_build_object(
      'credit_id', v_credit.id,
      'user_quest_id', v_credit.user_quest_id,
      'eligible_attributes', v_credit.eligible_attributes
    )
  );

  return jsonb_build_object(
    'credit', to_jsonb(v_credit),
    'attributes', to_jsonb(v_attributes),
    'attribute', v_attribute,
    'amount', p_amount,
    'remaining', v_credit.credits_awarded - v_credit.credits_spent
  );
end;
$function$;

revoke all on function public.system_allocate_attribute_credit_v1(uuid, text, integer) from public, anon;
grant execute on function public.system_allocate_attribute_credit_v1(uuid, text, integer) to authenticated;



