-- Exclude a previous class directive after switching classes.
CREATE OR REPLACE FUNCTION public.system_daily_command_brief_v1(p_assigned_for date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid := auth.uid();
  v_profile public.profiles;
  v_for_date date := coalesce(p_assigned_for, current_date);
  v_active_must public.user_quests;
  v_active_class public.user_quests;
  v_class_library public.quest_library;
  v_credits integer := 0;
  v_must_payload jsonb;
  v_class_payload jsonb;
begin
  if v_user is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  select * into v_profile
  from public.profiles
  where id = v_user;

  if not found then
    raise exception 'PROFILE_NOT_READY';
  end if;

  select * into v_active_must
  from public.user_quests uq
  where uq.user_id = v_user
    and uq.quest_type = 'MUST'
    and uq.assigned_for = v_for_date
    and uq.status = 'ACCEPTED'
    and (uq.expires_at is null or uq.expires_at >= now())
  order by uq.expires_at asc nulls last, uq.created_at asc
  limit 1;

  if found then
    v_must_payload := jsonb_build_object(
      'status', 'ACTIVE',
      'title', v_active_must.title_snapshot,
      'objective', v_active_must.objective_snapshot,
      'category', v_active_must.category,
      'xp', v_active_must.xp_reward,
      'penalty', v_active_must.xp_penalty,
      'expires_at', v_active_must.expires_at,
      'quest_id', v_active_must.id
    );
  else
    v_must_payload := jsonb_build_object(
      'status', 'NONE',
      'title', 'NO MUST DIRECTIVE ACTIVE',
      'objective', 'Open the Quest Board when you are ready to accept a 24-hour directive.',
      'xp', 0,
      'penalty', 0
    );
  end if;

  select * into v_active_class
  from public.user_quests uq
  where uq.user_id = v_user
    and uq.quest_type = 'CLASS'
    and exists(select 1 from public.quest_library current_quest where current_quest.id=uq.quest_id and upper(v_profile.class)=any(current_quest.class_affinity))
    and uq.assigned_for = v_for_date
    and uq.status in ('ASSIGNED', 'ACCEPTED', 'COMPLETED')
  order by
    case uq.status when 'ASSIGNED' then 0 when 'ACCEPTED' then 1 else 2 end,
    uq.created_at asc
  limit 1;

  if found then
    select * into v_class_library
    from public.quest_library q
    where q.id = v_active_class.quest_id;

    v_class_payload := jsonb_build_object(
      'status', case when v_active_class.status = 'COMPLETED' then 'COMPLETE' else 'READY' end,
      'code', coalesce(v_class_library.code, v_active_class.metadata->>'library_code', ''),
      'title', v_active_class.title_snapshot,
      'objective', v_active_class.objective_snapshot,
      'message', coalesce(v_class_library.system_message, 'Class alignment directive selected from the live rotation.'),
      'category', v_active_class.category,
      'xp', v_active_class.xp_reward,
      'attribute', v_active_class.attribute_reward,
      'attribute_delta', v_active_class.attribute_delta,
      'proof_type', coalesce(v_class_library.metadata->>'proof_type', 'HONOR'),
      'rotation_window_days', 7,
      'rotation_mode', 'ASSIGNED_TODAY'
    );
  else
    select * into v_class_library
    from public.quest_library q
    where q.active = true
      and q.quest_type = 'CLASS'
      and q.min_level <= coalesce(v_profile.level, 1)
      and upper(v_profile.class) = any(q.class_affinity)
      and not exists (
        select 1
        from public.user_quests uq
        where uq.user_id = v_user
          and uq.quest_id = q.id
          and uq.assigned_for >= v_for_date - 6
      )
    order by md5(v_user::text || ':' || v_for_date::text || ':' || q.id::text)
    limit 1;

    if not found then
      select * into v_class_library
      from public.quest_library q
      where q.active = true
        and q.quest_type = 'CLASS'
        and q.min_level <= coalesce(v_profile.level, 1)
        and upper(v_profile.class) = any(q.class_affinity)
      order by md5(v_user::text || ':' || v_for_date::text || ':' || q.id::text)
      limit 1;
    end if;

    if found then
      v_class_payload := jsonb_build_object(
        'status', 'READY',
        'code', v_class_library.code,
        'title', v_class_library.title,
        'objective', v_class_library.objective,
        'message', coalesce(v_class_library.system_message, 'Class alignment directive selected from the live rotation.'),
        'category', v_class_library.category,
        'xp', v_class_library.xp_reward,
        'attribute', v_class_library.attribute_reward,
        'attribute_delta', v_class_library.attribute_delta,
        'proof_type', coalesce(v_class_library.metadata->>'proof_type', 'HONOR'),
        'rotation_window_days', 7,
        'rotation_mode', 'UNUSED_7_DAY_ROTATION'
      );
    else
      v_class_payload := jsonb_build_object(
        'status', 'NONE',
        'title', 'CLASS DIRECTIVE UNAVAILABLE',
        'objective', 'The class catalogue is synchronizing. Retry without resetting progression.',
        'xp', 0,
        'rotation_window_days', 7
      );
    end if;
  end if;

  select coalesce(sum(greatest(0, credit.credits_awarded - credit.credits_spent)), 0)
  into v_credits
  from public.attribute_credit_ledger credit
  where credit.user_id = v_user;

  return jsonb_build_object(
    'status', 'READY',
    'assigned_for', v_for_date,
    'generated_at', now(),
    'must_directive', v_must_payload,
    'class_directive', v_class_payload,
    'progress', jsonb_build_object(
      'unspent_credits', v_credits,
      'level', v_profile.level,
      'streak', v_profile.streak,
      'class', v_profile.class
    ),
    'rotation', jsonb_build_object(
      'window_days', 7,
      'rule', 'NO_REPEAT_WHEN_A_COMPATIBLE_UNUSED_DIRECTIVE_EXISTS'
    )
  );
end;
$function$;

-- Do not resume an incompatible timer after a class change.
CREATE OR REPLACE FUNCTION public.system_start_timed_workout_v1(p_workout_id bigint, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid := auth.uid();
  v_workout public.workout_templates;
  v_timer public.workout_timer_sessions;
  v_mode text;
  v_target_seconds integer;
  v_elapsed_seconds integer := 0;
begin
  if v_user is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  if p_workout_id is null or p_workout_id <= 0 then
    raise exception 'INVALID_WORKOUT_ID';
  end if;

  if not public.system_workout_available(p_workout_id) then
    raise exception 'WORKOUT_LOCKED_OR_UNAVAILABLE';
  end if;

  select * into v_workout
  from public.workout_templates
  where id = p_workout_id
    and active = true;

  if not found then
    raise exception 'WORKOUT_NOT_FOUND';
  end if;

  v_mode := public.system_workout_verification_mode_v1(v_workout.id);
  if v_mode <> 'TIMER' then
    raise exception 'WORKOUT_DOES_NOT_USE_TIMER';
  end if;

  -- A player may resume an in-progress timer, but cannot run several timers
  -- in parallel. Timers get a 2x-duration grace window for a normal call,
  -- hydration, or browser backgrounding; after that they expire safely.
  select * into v_timer
  from public.workout_timer_sessions
  where user_id = v_user
    and status = 'ACTIVE'
  order by started_at desc
  limit 1
  for update;

  if found then
    v_elapsed_seconds := greatest(
      0,
      floor(extract(epoch from clock_timestamp() - v_timer.started_at))::integer
    );

    if v_elapsed_seconds <= v_timer.target_seconds * 2 and public.system_workout_available(v_timer.workout_id) then
      select * into v_workout
      from public.workout_templates
      where id = v_timer.workout_id;

      return jsonb_build_object(
        'session', to_jsonb(v_timer),
        'workout', to_jsonb(v_workout),
        'resumed', true,
        'server_now', clock_timestamp()
      );
    end if;

    update public.workout_timer_sessions
    set
      status = 'EXPIRED',
      updated_at = clock_timestamp()
    where id = v_timer.id;
  end if;

  v_target_seconds := least(
    7200,
    greatest(
      60,
      coalesce(v_workout.estimated_minutes, 10) * 60
    )
  );

  insert into public.workout_timer_sessions(
    user_id,
    workout_id,
    workout_name_snapshot,
    target_seconds,
    metadata
  )
  values (
    v_user,
    v_workout.id,
    v_workout.name,
    v_target_seconds,
    coalesce(p_metadata, '{}'::jsonb) || jsonb_build_object(
      'verification_mode', 'SERVER_TIMER'
    )
  )
  returning * into v_timer;

  return jsonb_build_object(
    'session', to_jsonb(v_timer),
    'workout', to_jsonb(v_workout),
    'resumed', false,
    'server_now', clock_timestamp()
  );
end;
$function$;



-- Original migration: 20260925154139_player_foundation_scan_v2_9_4.sql
create or replace function public.system_save_foundation_scan_v1(
  p_scan jsonb,
  p_fuel jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_user uuid := auth.uid();
  v_scan jsonb := coalesce(p_scan, '{}'::jsonb);
  v_fuel jsonb := coalesce(p_fuel, '{}'::jsonb);
  v_primary_focus text;
  v_experience text;
  v_activity_level text;
  v_daily_minutes integer;
  v_meals_per_day text;
  v_equipment text;
  v_weight_text text;
  v_height_text text;
  v_calorie_text text;
  v_protein_text text;
  v_weight numeric;
  v_height numeric;
  v_calorie_target integer := 0;
  v_protein_target integer := 0;
  v_recommended_goal text := 'MAINTAIN';
  v_selected_goal text;
  v_profile_data jsonb;
  v_clean_scan jsonb;
  v_clean_fuel jsonb;
begin
  if v_user is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  if jsonb_typeof(v_scan) <> 'object' or jsonb_typeof(v_fuel) <> 'object' then
    raise exception 'INVALID_FOUNDATION_SCAN';
  end if;

  v_primary_focus := upper(trim(coalesce(v_scan->>'primaryFocus', '')));
  v_experience := upper(trim(coalesce(v_scan->>'experience', '')));
  v_activity_level := upper(trim(coalesce(v_scan->>'activityLevel', '')));
  v_meals_per_day := upper(trim(coalesce(v_scan->>'mealsPerDay', '')));
  v_equipment := upper(trim(coalesce(v_scan->>'equipment', '')));

  if v_primary_focus not in ('STRENGTH', 'BODY_COMPOSITION', 'FITNESS', 'FOCUS', 'CONFIDENCE', 'KNOWLEDGE') then
    raise exception 'INVALID_FOUNDATION_FOCUS';
  end if;

  if v_experience not in ('NEW', 'RETURNING', 'REGULAR', 'EXPERIENCED') then
    raise exception 'INVALID_FOUNDATION_EXPERIENCE';
  end if;

  if v_activity_level not in ('LOW', 'MODERATE', 'ACTIVE', 'VERY_ACTIVE') then
    raise exception 'INVALID_ACTIVITY_LEVEL';
  end if;

  if coalesce(v_scan->>'dailyMinutes', '') not in ('10', '20', '30', '45', '60') then
    raise exception 'INVALID_DAILY_MINUTES';
  end if;
  v_daily_minutes := (v_scan->>'dailyMinutes')::integer;

  if v_meals_per_day not in ('ONE_TO_TWO', 'THREE', 'FOUR_PLUS', 'IRREGULAR') then
    raise exception 'INVALID_MEAL_RHYTHM';
  end if;

  if v_equipment not in ('BODYWEIGHT', 'HOME', 'GYM', 'OUTDOOR') then
    raise exception 'INVALID_TRAINING_ACCESS';
  end if;

  v_weight_text := nullif(trim(coalesce(v_scan->>'weightKg', '')), '');
  if v_weight_text is not null then
    if v_weight_text !~ '^[0-9]+(\.[0-9]+)?$' then
      raise exception 'INVALID_WEIGHT';
    end if;
    v_weight := v_weight_text::numeric;
    if v_weight < 30 or v_weight > 350 then
      raise exception 'INVALID_WEIGHT';
    end if;
  end if;

  v_height_text := nullif(trim(coalesce(v_scan->>'heightCm', '')), '');
  if v_height_text is not null then
    if v_height_text !~ '^[0-9]+(\.[0-9]+)?$' then
      raise exception 'INVALID_HEIGHT';
    end if;
    v_height := v_height_text::numeric;
    if v_height < 120 or v_height > 230 then
      raise exception 'INVALID_HEIGHT';
    end if;
  end if;

  if v_primary_focus = 'STRENGTH' and v_weight is not null and v_height is not null
     and v_weight / power(v_height / 100, 2) < 20.5 then
    v_recommended_goal := 'BULK';
  end if;

  v_selected_goal := upper(trim(coalesce(nullif(v_fuel->>'goal', ''), v_recommended_goal)));
  if v_selected_goal not in ('CUT', 'MAINTAIN', 'BULK') then
    raise exception 'INVALID_FUEL_GOAL';
  end if;

  v_calorie_text := nullif(trim(coalesce(v_fuel->>'calorieTarget', '')), '');
  if v_calorie_text is not null then
    if v_calorie_text !~ '^[0-9]+$' then
      raise exception 'INVALID_CALORIE_TARGET';
    end if;
    v_calorie_target := v_calorie_text::integer;
    if v_calorie_target <> 0 and (v_calorie_target < 1200 or v_calorie_target > 5000) then
      raise exception 'INVALID_CALORIE_TARGET';
    end if;
  end if;

  v_protein_text := nullif(trim(coalesce(v_fuel->>'proteinTarget', '')), '');
  if v_protein_text is not null then
    if v_protein_text !~ '^[0-9]+$' then
      raise exception 'INVALID_PROTEIN_TARGET';
    end if;
    v_protein_target := v_protein_text::integer;
    if v_protein_target <> 0 and (v_protein_target < 45 or v_protein_target > 250) then
      raise exception 'INVALID_PROTEIN_TARGET';
    end if;
  end if;

  v_clean_scan := jsonb_strip_nulls(
    jsonb_build_object(
      'primaryFocus', v_primary_focus,
      'experience', v_experience,
      'activityLevel', v_activity_level,
      'dailyMinutes', v_daily_minutes,
      'weightKg', v_weight,
      'heightCm', v_height,
      'mealsPerDay', v_meals_per_day,
      'equipment', v_equipment,
      'recommendedFuelGoal', v_recommended_goal,
      'selectedFuelGoal', v_selected_goal,
      'estimatedCalorieTarget', v_calorie_target,
      'estimatedProteinTarget', v_protein_target,
      'version', 1,
      'completedAt', clock_timestamp()
    )
  );

  v_clean_fuel := jsonb_build_object(
    'goal', v_selected_goal,
    'calorieTarget', v_calorie_target,
    'proteinTarget', v_protein_target
  );

  update public.profiles
  set
    profile_data = coalesce(profile_data, '{}'::jsonb)
      || jsonb_build_object(
        'foundationScan', v_clean_scan,
        'fuel', v_clean_fuel
      ),
    updated_at = now()
  where id = v_user
  returning profile_data into v_profile_data;

  if not found then
    raise exception 'PROFILE_NOT_INITIALIZED';
  end if;

  return jsonb_build_object(
    'foundationScan', v_profile_data->'foundationScan',
    'fuel', v_profile_data->'fuel'
  );
end;
$function$;

revoke all on function public.system_save_foundation_scan_v1(jsonb, jsonb) from public, anon;
grant execute on function public.system_save_foundation_scan_v1(jsonb, jsonb) to authenticated;


-- Original migration: 20260925155346_player_foundation_scan_routine_preferences.sql
create or replace function public.system_save_foundation_scan_v1(
  p_scan jsonb,
  p_fuel jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_user uuid := auth.uid();
  v_scan jsonb := coalesce(p_scan, '{}'::jsonb);
  v_fuel jsonb := coalesce(p_fuel, '{}'::jsonb);
  v_primary_focus text;
  v_experience text;
  v_activity_level text;
  v_main_obstacle text;
  v_daily_minutes integer;
  v_meals_per_day text;
  v_equipment text;
  v_food_preference text;
  v_food_budget text;
  v_weight_text text;
  v_height_text text;
  v_calorie_text text;
  v_protein_text text;
  v_weight numeric;
  v_height numeric;
  v_calorie_target integer := 0;
  v_protein_target integer := 0;
  v_recommended_goal text := 'MAINTAIN';
  v_selected_goal text;
  v_profile_data jsonb;
  v_clean_scan jsonb;
  v_clean_fuel jsonb;
begin
  if v_user is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  if jsonb_typeof(v_scan) <> 'object' or jsonb_typeof(v_fuel) <> 'object' then
    raise exception 'INVALID_FOUNDATION_SCAN';
